public class Grid {
    public static void main(String[] args) {
        int[][] grid = {{3, 8, 1},
                        {4, 0, 6},
                        {9, 2, 7}};

        for (int c = 0; c < grid[0].length; c++) {
            int sum = 0;
            for (int r = 0; r < grid.length; r++) {
                sum += grid[r][c];
            }
            System.out.println("column " + c + " sums to " + sum);
        }
    }
}
